-- LISTIA AI Engine speech capability.
insert into private.ai_models(model_key,provider_key,provider_model_id,display_name,family,lifecycle_status,input_modalities,output_modalities,route_tags,capabilities,cost_profile,deprecation_risk,updated_at)
values('openai:gpt-4o-mini-tts','openai','gpt-4o-mini-tts','GPT-4o Mini TTS','gpt-4o-mini','verified',array['text']::text[],array['audio']::text[],array['tts','speech','voice']::text[],jsonb_build_object('tts',true,'instructions',true,'mp3',true),jsonb_build_object('pricing_mode','provider_metered'),'normal',now())
on conflict(model_key) do update set provider_model_id=excluded.provider_model_id,display_name=excluded.display_name,lifecycle_status=excluded.lifecycle_status,input_modalities=excluded.input_modalities,output_modalities=excluded.output_modalities,route_tags=excluded.route_tags,capabilities=excluded.capabilities,updated_at=now();

insert into private.ai_route_policies(task_type,quality_tier,strategy,primary_models,reviewer_models,fallback_models,required_validators,max_parallel,max_attempts,escalate_on_failure,optimization_objective,active,notes)
values('tts','q1','single_then_validate',array['openai:gpt-4o-mini-tts'],array[]::text[],array[]::text[],array['audio_nonempty'],1,1,false,'lowest_cost_passing_quality',true,'LISTIA AI Engine TTS capability. Add future speech adapters here without changing product callers.')
on conflict(task_type,quality_tier) do update set strategy=excluded.strategy,primary_models=excluded.primary_models,reviewer_models=excluded.reviewer_models,fallback_models=excluded.fallback_models,required_validators=excluded.required_validators,max_parallel=excluded.max_parallel,max_attempts=excluded.max_attempts,escalate_on_failure=excluded.escalate_on_failure,optimization_objective=excluded.optimization_objective,active=true,notes=excluded.notes;
